BEGIN;CREATE TABLE IF NOT EXISTS replacement_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assignment_id uuid NOT NULL REFERENCES work_assignments(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','matched','resolved','cancelled')),replacement_professional_id uuid REFERENCES professional_profiles(id) ON DELETE SET NULL,reason text,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,UNIQUE(assignment_id,status));ALTER TABLE replacement_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE replacement_requests FORCE ROW LEVEL SECURITY;CREATE POLICY replacement_requests_tenant_isolation ON replacement_requests USING(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting('app.tenant_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON replacement_requests TO app_runtime;COMMIT;
